import{useState}from'react';import{Link}from'react-router-dom';import{Check,ArrowRight,ArrowLeft}from'lucide-react';import{useStore}from'../context/Store';import{appendAdminRow}from'../data/siteConfig';
const steps=['Business','Contact','Address','Credentials','Review'];
export default function Application(){const[step,setStep]=useState(0);const[done,setDone]=useState(false);const[data,setData]=useState<Record<string,string>>({country:'United States',type:'Independent retailer'});const{showToast}=useStore();const field=(name:string,label:string,type='text')=><label>{label}<input type={type} value={data[name]||''} onChange={e=>setData({...data,[name]:e.target.value})} required/></label>;if(done)return <div className="application success-page"><span><Check/></span><h1>Application received.</h1><p>Thank you, {data.contact||'business applicant'}. Your application has been saved locally for this demonstration. A real workflow would now begin business verification.</p><Link className="btn dark" to="/">Return home</Link></div>;return <div className="application container"><div className="application-head"><p className="eyebrow">BECOME A WHOLESALE CUSTOMER</p><h1>Let’s get to know your business.</h1><p>Complete the application below. Your information helps us verify eligibility and provide the right account experience.</p></div><div className="stepper">{steps.map((s,i)=><div className={(i===step?'active ':'')+(i<step?'complete':'')} key={s}><span>{i<step?<Check/>:i+1}</span><b>{s}</b></div>)}</div><form className="application-form" onSubmit={e=>{e.preventDefault();if(step<4)setStep(step+1);else{localStorage.setItem('ms-application',JSON.stringify(data));appendAdminRow('applications',[data.legal||'New business',data.contact||'Applicant',new Date().toLocaleDateString('en-US',{month:'short',day:'2-digit'}),data.resale?'Credentials supplied':'Pending documents','Pending']);setDone(true);showToast('Application submitted')}}}><h2>{['Tell us about your business','Primary contact','Business address','Wholesale credentials','Review your application'][step]}</h2><p>{['We partner with qualified retailers, salons and ecommerce businesses.','Who should we contact about this account?','Where is your business located?','Provide the details used to verify wholesale eligibility.','Confirm your information before submitting.'][step]}</p><div className="form-grid">{step===0&&<>{field('legal','Legal business name')}{field('dba','DBA / trading name')}<label>Business type<select value={data.type} onChange={e=>setData({...data,type:e.target.value})}><option>Independent retailer</option><option>Salon / spa</option><option>Ecommerce retailer</option><option>Multi-location retailer</option><option>Other</option></select></label>{field('website','Business website')}{field('years','Years in business','number')}</>}{step===1&&<>{field('contact','Full name')}{field('position','Position / title')}{field('email','Business email','email')}{field('phone','Phone','tel')}</>}{step===2&&<>{field('address','Street address')}{field('city','City')}{field('state','State')}{field('zip','ZIP code')}<label>Country<select><option>United States</option></select></label></>}{step===3&&<>{field('tax','Federal tax ID')}{field('resale','Resale certificate number')}<label className="full upload">Resale certificate document<span>Document upload placeholder · PDF, JPG or PNG</span><input type="file"/></label><label className="check full"><input type="checkbox" required/> I confirm this application is for a legitimate business purchase.</label></>}{step===4&&<div className="review full">{Object.entries(data).map(([k,v])=>v&&<div key={k}><small>{k.toUpperCase()}</small><b>{v}</b></div>)}</div>}</div><div className="form-actions">{step>0&&<button type="button" className="btn outline" onClick={()=>setStep(step-1)}><ArrowLeft/> Back</button>}<button className="btn dark">{step===4?'Submit application':'Continue'} <ArrowRight/></button></div></form></div>}
